    about: { title: 'STARTIN-DE là gì?', lead: 'STARTIN-DE được xây dựng để giúp người Việt tìm hiểu con đường học tập, học nghề và phát triển sự nghiệp tại Đức một cách rõ ràng hơn. Chúng tôi tập trung vào thông tin có thể kiểm tra, công cụ chuẩn bị thực tế và cách tư vấn minh bạch.', values: [{ title: 'Minh bạch', body: 'Nói rõ điều đã có, điều đang phát triển và điều cần được xác minh.' }, { title: 'Thiết thực', body: 'Tập trung vào tài liệu, câu hỏi và bước chuẩn bị mà bạn có thể chủ động kiểm tra.' }, { title: 'Tôn trọng lựa chọn của bạn', body: 'Cung cấp thông tin để bạn tự cân nhắc; không gây áp lực bằng lời hứa kết quả.' }], imageAlt: 'Khu phố cổ với những ngôi nhà nhiều màu sắc ở Tübingen, Đức' },
    partners: { title: 'Hợp tác cùng STARTIN-DE', lead: 'Chúng tôi mong muốn kết nối với doanh nghiệp đào tạo nghề, cơ sở giáo dục và các đối tác uy tín tại Đức để phát triển thông tin và hoạt động chuẩn bị có trách nhiệm.', note: 'Mọi hợp tác chỉ được xác lập sau khi hai bên cùng xem xét mục tiêu, trách nhiệm và khuôn khổ pháp lý. Hiện chưa có quan hệ đối tác nào được công bố trên website.', contactPending: 'Thông tin liên hệ công khai sẽ được bổ sung sau khi STARTIN-DE xác nhận kênh tiếp nhận. Hiện website chưa gửi được yêu cầu hợp tác.' },
    contact: { title: 'Liên hệ STARTIN-DE', lead: 'Bạn có câu hỏi về các công cụ, nội dung hoặc khả năng hợp tác? Hãy cho chúng tôi biết bạn cần hỗ trợ điều gì.', pending: 'Kênh liên hệ chưa được xác nhận', detail: 'Chúng tôi chưa được cung cấp địa chỉ email hoặc hộp thư nhận yêu cầu đã xác minh. Vì vậy website chưa hiển thị biểu mẫu gửi đi để tránh làm mất thông tin của bạn.', noSensitive: 'Không gửi hộ chiếu, giấy tờ định danh hoặc tài liệu ứng tuyển qua các kênh công khai.' },
    legal: { privacyTitle: 'Thông báo quyền riêng tư', privacyLead: 'Thông tin quyền riêng tư công khai đang chờ STARTIN-DE xác nhận pháp nhân, nhà cung cấp, nơi xử lý dữ liệu, thời hạn lưu trữ và kênh liên hệ. Không dùng bản nháp này làm tư vấn pháp lý.', termsTitle: 'Điều khoản sử dụng', termsLead: 'Điều khoản công khai đang chờ rà soát và phê duyệt. Các dịch vụ thương mại và thanh toán vẫn bị tắt cho đến khi nội dung và quy trình được xác nhận.', refundsTitle: 'Hủy dịch vụ và hoàn tiền', refundsLead: 'Chính sách hủy và hoàn tiền chưa được phê duyệt. Website hiện không bán gói dịch vụ hoặc nhận thanh toán.', blocker: 'Nội dung này chưa phải chính sách đã được phê duyệt.', back: 'Quay lại trang chủ' },
    footerNav: { ausbildung: 'Ausbildung', study: 'Du học', work: 'Làm việc', opportunities: 'Cơ hội', tools: 'Công cụ', guides: 'Cẩm nang', services: 'Dịch vụ', pricing: 'Bảng giá', about: 'Giới thiệu', partners: 'Hợp tác', contact: 'Liên hệ', privacy: 'Quyền riêng tư', terms: 'Điều khoản', refunds: 'Hủy và hoàn tiền' },
    shared: { learn: 'Tìm hiểu thêm', officialSources: 'Nguồn tham khảo chính thức', updated: 'Nguồn được kiểm tra', notAdvice: 'Nội dung mang tính thông tin, không thay thế hướng dẫn của cơ quan có thẩm quyền.', placeholderPrefix: 'Gợi ý hình ảnh', coming: 'Đang phát triển', available: 'Đã triển khai', indicative: 'Giá tham khảo', detailsPending: 'Chi tiết sẽ được công bố trước khi mở dịch vụ.', notOffered: 'Chưa cung cấp', noCheckout: 'Chưa mở đăng ký hoặc thanh toán', documentsCta: 'Kiểm tra hồ sơ', browseGuides: 'Đọc cẩm nang', readGuide: 'Đọc hướng dẫn', serviceDetail: 'Xem phạm vi dịch vụ', external: 'Mở trang chính thức' },
